import sys
sys.path.insert(0,"/tmp/campaign_py")
from pathlib import Path
import json,html,base64,hashlib,subprocess,datetime,csv
from collections import Counter
root=Path('/workspace/Campaign');out=root/'REVIEW_200';plan=json.loads((out/'PLAN_200.json').read_text());subprocess.run(['node',str(out/'scripts/render.js')],check=True,capture_output=True)
import cairosvg
cards=[];mapping=[]
for row in plan:
 pos=row['position'];stem=f'Level{pos:03}';packfile=out/'packs'/f'{stem}.rrpack.json';recfile=out/'validation'/f'{pos:03}.json';svg=out/'previews'/f'{stem}.svg';png=svg.with_suffix('.png');rec=json.loads(recfile.read_text()) if recfile.exists() else None
 if svg.exists() and(not png.exists() or png.stat().st_mtime<svg.stat().st_mtime):cairosvg.svg2png(url=str(svg),write_to=str(png),output_width=660)
 pack=json.loads(packfile.read_text()) if packfile.exists() else {};parts=pack.get('runtime',{}).get('parts',[]);rings=sum(p['kind']=='ring' for p in parts);sticks=sum(p['kind']=='stick' for p in parts);fish=sum(bool(p.get('canCollect')) for p in parts);bombs=sum(p['kind']=='bomb' for p in parts);chains=[{'id':p['partId'],'count':p['lockCount']} for p in parts if p.get('lockCount',0)>0]
 status='Đã kiểm định' if rec else 'Đang xử lý';source=row.get('source_position',row.get('candidate',''));target=row.get('target_rings','?');warning=len(rec.get('warnings',[])) if rec else 0
 title=f'#{pos:03} · {row["type"]}';image=f'<img loading="lazy" width="660" alt="{title}" src="data:image/png;base64,{base64.b64encode(png.read_bytes()).decode()}">' if png.exists() else '<div class="placeholder">Đang tạo ảnh</div>'
 details=f'R {rings} / curve {target} · Stick {sticks} · Cá {fish} · Xích {len(chains)} · Bom {bombs}' if pack else f'Curve R {target}'
 note=row.get('specific_feedback') or row.get('reason','');extra=[]
 if rec and rings!=target:extra.append('Ngoại lệ R theo nguồn GD duyệt / chính sách giữ vòng nguồn.' if row['type']!='Normal' else 'Sai lệch R — xem mapping.')
 if rec and rec.get('routeNeedsBomb'):extra.append('Lời giải kiểm tra có sử dụng bom.')
 if warning:extra.append(f'{warning} cảnh báo tư vấn được ghi trong báo cáo.')
 if chains:extra.append('Xích: '+', '.join(str(c['count']) for c in chains)+' nấc; đã mô phỏng giảm đếm.')
 links=f'<a href="packs/{stem}.rrpack.json">Pack</a> · <a href="validation/{pos:03}.json">Kiểm định</a>' if rec else ''
 cards.append(f'<article id="level-{pos}" data-type="{row["type"]}" data-block="{(pos-1)//20}" data-status="{bool(rec)}"><h2>{title}</h2><p class="status">{status} · Nguồn {html.escape(str(source))}</p>{image}<p><b>{details}</b></p><p>{html.escape(str(row.get("theme", "")))}</p><details><summary>Ghi chú / kiểm tra</summary><p>{html.escape(note)}</p><p>{html.escape(" ".join(extra))}</p>{links}</details></article>')
 mapping.append(dict(position=pos,type=row['type'],source=source,targetR=target,actualR=rings if pack else None,fish=fish,chains=chains,bombs=bombs,status='qualified' if rec else 'pending',warnings=warning,pack=f'packs/{stem}.rrpack.json',geometryChanged=rec.get('geometryChanged',False) if rec else None,routeNeedsBomb=rec.get('routeNeedsBomb',False) if rec else None))
completed=sum(m['status']=='qualified' for m in mapping);now=datetime.datetime.now(datetime.timezone.utc).isoformat();summary={'positions':200,'qualified':completed,'pending':200-completed,'updatedAt':now,'typeCounts':dict(Counter(m['type'] for m in mapping)),'chainPositions':[m['position'] for m in mapping if m['chains']],'bombNormalPositions':[m['position'] for m in mapping if m['type']=='Normal' and m['bombs']],'curveRExceptions':[{'position':m['position'],'target':m['targetR'],'actual':m['actualR']} for m in mapping if m['actualR'] is not None and m['actualR']!=m['targetR']],'nativeUnity':'not run','difficultyScope':'R curve and source selection checked. Human difficulty/beauty require GD review; no drag-count difficulty claim.'}
(out/'MAPPING_200.json').write_text(json.dumps(mapping,ensure_ascii=False,indent=2));(out/'STATUS.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2));
with (out/'MAPPING_200.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(mapping[0]));w.writeheader();w.writerows(mapping)
options='<option value="all">Tất cả 200</option>'+''.join(f'<option value="{i}">{20*i+1}–{20*i+20}</option>' for i in range(10))
page='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campaign · Review 200</title><style>body{margin:0;background:#f2eee7;color:#252b30;font:15px system-ui}header{position:sticky;top:0;background:#fffef3ef;padding:12px 20px;z-index:2;border-bottom:1px solid #ccc}h1{font-size:23px;margin:0 0 6px}a{color:#1266a3}select,input{padding:7px;margin:4px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(315px,1fr));gap:16px;padding:20px}article{background:white;border-radius:12px;padding:15px;scroll-margin-top:180px;box-shadow:0 2px 8px #0001}h2{font-size:20px;margin:0}p{margin:7px 0}img{width:100%;height:330px;object-fit:contain;background:#fbf1e0;border-radius:8px}.status{color:#537065}.placeholder{height:330px;display:grid;place-items:center;background:#eee}details{font-size:13px}footer{padding:20px}</style><header><h1>Campaign · Bộ review 200 level</h1><div>__COUNT__/200 đã kiểm định · __TIME__</div><p>Ảnh PNG nhúng trực tiếp, mở offline được. Trang tự cập nhật khi có kết quả mới.</p><select id="block">__OPTIONS__</select><select id="type"><option value="all">Mọi loại</option><option>Normal</option><option>Special</option><option>Symmetrical</option></select><input id="jump" type="number" min="1" max="200" placeholder="Tới level…"><button onclick="jump()">Đi</button> · <a href="MAPPING_200.csv">Mapping CSV</a> · <a href="STATUS.json">Trạng thái</a> · <a href="README.md">Phạm vi kiểm tra</a></header><main>__CARDS__</main><footer>Kiểm tra bằng JS runtime của repository; chưa chạy Unity native. Số vòng là một chỉ số tham chiếu, không thay thế đánh giá độ khó của GD.</footer><script>function filter(){document.querySelectorAll('article').forEach(e=>e.hidden=!((block.value==='all'||e.dataset.block===block.value)&&(type.value==='all'||e.dataset.type===type.value)))}block.onchange=type.onchange=filter;function jump(){block.value=type.value='all';filter();location.hash='level-'+document.getElementById('jump').value}let version='__VERSION__';setInterval(async()=>{try{let r=await fetch('version.json?t='+Date.now(),{cache:'no-store'}),v=await r.json();if(v.version!==version)location.reload()}catch(e){}},2000)</script></html>'''
version=hashlib.sha256((str(completed)+json.dumps([(m['position'],m['status'],m['actualR']) for m in mapping])).encode()).hexdigest()[:16]
for key,val in {'COUNT':str(completed),'TIME':now,'OPTIONS':options,'CARDS':''.join(cards),'VERSION':version}.items():page=page.replace('__'+key+'__',val)
(out/'index.html').write_text(page);(out/'version.json').write_text(json.dumps({'version':version,'completed':completed}));print(f'Review {completed}/200; PNG {len(list((out/"previews").glob("*.png")))}')
